/** 🧮️ Shared stroke alpha vectors and independent SVG paint. */
import {expect,test} from "vitest";
import Ajv from "ajv";
import sharp from "sharp";
import {createCanvas} from "@napi-rs/canvas";
import fixture from "../🧫️fixtures/🔣️.json";
import schema from "../🧬️schema/🔣️.json";
import {StrokeOutlineJob,prepareStroke,type StrokeOutlineInput} from "../🟦️.ts";
import {CoverageJob} from "../../../../🔲️pixels/🖊️coverage/🟦️.ts";
import type {Vec2} from "../../../🟦️.ts";
const validate=new Ajv({strict:true}).compile(schema);
function input(row:typeof fixture[number]):StrokeOutlineInput {
 return {contours:[{points:row.points as Vec2[],closed:row.closed}],transform:[1,0,0,1,0,0],tolerance:.0001,style:{width:row.width,cap:row.cap as StrokeOutlineInput["style"]["cap"],join:row.join as StrokeOutlineInput["style"]["join"],miterLimit:row.miterLimit,dash:row.dash,dashOffset:row.dashOffset}};
}
function complete(source:StrokeOutlineInput,budget:number):Vec2[][] {
 const job=new StrokeOutlineJob(source);let work=0;
 for(let at=0;at<200000;at++){const p=job.advance(budget);expect(p.work-work).toBeLessThanOrEqual(budget);work=p.work;if(p.done)return job.result();}
 throw Error("Stroke preparation did not terminate");
}
function mask(source:StrokeOutlineInput,extent:readonly number[],budget:number):Uint8Array {
 const contours=complete(source,budget),coverage=new CoverageJob({width:extent[0]!,height:extent[1]!,contours,transform:source.transform,rule:"nonzero"});
 while(!coverage.advance(4096).done){}return coverage.result().coverage;
}
async function reference(source:StrokeOutlineInput,extent:readonly number[]):Promise<number[]> {
 const scale=128,w=extent[0]!,h=extent[1]!,s=source.style;
 const d=source.contours.filter(c=>c.points.length>1||c.closed).map(c=>c.points.length?`M${c.points.map(p=>p.join(",")).join("L")}${c.closed?"Z":""}`:"").join("");
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${w*scale}" height="${h*scale}" viewBox="0 0 ${w} ${h}"><path d="${d}" transform="matrix(${source.transform.join(" ")})" fill="none" stroke="red" stroke-width="${s.width}" stroke-linecap="${s.cap}" stroke-linejoin="${s.join}" stroke-miterlimit="${s.miterLimit}" stroke-dasharray="${s.dash.length?s.dash.join(" "):"none"}" stroke-dashoffset="${s.dashOffset}"/></svg>`;
 const pixels=await sharp(Buffer.from(svg)).ensureAlpha().raw().toBuffer(),out:number[]=[];
 for(let at=0;at<w*h;at++){const x=at%w,y=Math.floor(at/w);let sum=0;for(let dy=0;dy<scale;dy++)for(let dx=0;dx<scale;dx++)sum+=pixels[((y*scale+dy)*w*scale+x*scale+dx)*4+3]!;out.push(Math.round(sum/(scale*scale)));}
 return out;
}
for(const row of fixture)test(row.name,async()=>{
 const source=input(row),before=structuredClone(source);expect(validate(source)).toBe(true);
 for(const budget of [1,7,4096])expect([...mask(source,row.extent,budget)]).toEqual(row.expected);
 expect(source).toEqual(before);const oracle=await reference(source,row.extent);
 for(let at=0;at<row.expected.length;at++)expect(Math.abs(row.expected[at]!-oracle[at]!)).toBeLessThanOrEqual(2);
});
test("crossings, short joins, reversals and dash degeneracies match SVG under affine transforms",async()=>{
 const paths:StrokeOutlineInput["contours"][]=[
  [{points:[[1,2],[5,2],[1,4],[5,4]],closed:false}],
  [{points:[[1,2],[1.1,2],[1.1,2.1]],closed:false}],
  [{points:[[1,2],[5,2],[1,2]],closed:false}],
  [{points:[[1,1],[5,1],[5,5],[1,5]],closed:true}],
  [{points:[[3,3],[3,3]],closed:false}],
  [{points:[[3,3],[3,3]],closed:true}],
  [{points:[[3,3]],closed:false}],
  [{points:[[3,3]],closed:true}],
 ];
 for(const cap of ["butt","round","square"] as const)for(const join of ["miter","round","bevel"] as const)for(let at=0;at<paths.length;at++)for(const dash of [[],[1,0],[0,1],[1,2,3],[0,0,1,1],[.3,0,.4,.2]]) {
  const source:StrokeOutlineInput={contours:paths[at]!,transform:at%2?[.8,.2,-.3,1,1,0]:[-1,0,.2,1,6,0],tolerance:.0001,style:{width:.8,cap,join,miterLimit:4,dash,dashOffset:.35}},actual=mask(source,[6,6],4096),oracle=await reference(source,[6,6]);
  const delta=Math.max(...actual.map((value,p)=>Math.abs(value-oracle[p]!)));if(delta>2)throw Error(JSON.stringify({cap,join,at,dash,actual:[...actual],oracle,delta}));expect(delta).toBeLessThanOrEqual(2);
 }
},30000);
test("invalid contracts and cancelled preparation cannot expose partial geometry",()=>{
 const source=input(fixture[4]!);
 for(const steps of [0,1,5,20]){const job=new StrokeOutlineJob(source);expect(()=>job.result()).toThrow();for(let at=0;at<steps;at++)job.advance(1);job.cancel();expect(()=>job.advance(1)).toThrow(/cancelled/);expect(()=>job.result()).toThrow(/cancelled/);}
 for(const patch of [{width:-1},{cap:"triangle"},{join:"arcs"},{miterLimit:0},{dash:[-1,2]},{dashOffset:NaN}])expect(()=>new StrokeOutlineJob({...source,style:{...source.style,...patch}} as StrokeOutlineInput)).toThrow();
 for(const grant of [0,-1,NaN,Infinity,1.5])expect(()=>new StrokeOutlineJob(source).advance(grant)).toThrow();
 const bad=new StrokeOutlineJob({...source,contours:[{points:[[NaN,0],[1,0]],closed:false}]});expect(()=>bad.advance(100)).toThrow();expect(()=>bad.result()).toThrow();
});
test("large crossing strokes fit the coverage point budget without a primitive-count cutoff",async()=>{
 const source=input(fixture[2]!);source.contours=[{points:Array.from({length:9001},(_,at)=>[at%2,1] as Vec2),closed:false}];
 expect([...mask(source,[1,2],4096)]).toEqual([255,255]);expect(await reference(source,[1,2])).toEqual([255,255]);
});
test("dash expansion has a geometry budget and never publishes an incomplete candidate",()=>{
 const source=input(fixture[2]!);source.style.dash=[.000001,.000001];const job=new StrokeOutlineJob(source);
 expect(()=>{while(!job.advance(4096).done){}}).toThrow(/budget/);expect(()=>job.result()).toThrow();
});
test("a moveto alone paints no square cap, matching the SVG rule and independent native canvas",()=>{
 const source=input(fixture[11]!);source.style.cap="square";expect([...mask(source,[2,2],4096)]).toEqual([0,0,0,0]);
 const canvas=createCanvas(2,2),ctx=canvas.getContext("2d");ctx.lineCap="square";ctx.lineWidth=2;ctx.moveTo(1,1);ctx.stroke();
 expect([...ctx.getImageData(0,0,2,2).data].filter((_,at)=>at%4===3)).toEqual([0,0,0,0]);
});
test("async stroke preparation yields, responds to cancellation and preserves published geometry",async()=>{
 const source=input(fixture[4]!),before=structuredClone(source),events:string[]=[];
 const timer=setTimeout(()=>events.push("timer"),0),polygons=await prepareStroke(source,{workBudget:7,onProgress:p=>events.push(p.phase)});clearTimeout(timer);
 expect(polygons.length).toBeGreaterThan(0);expect(events).toContain("outlining");expect(events.indexOf("timer")).toBeGreaterThanOrEqual(0);expect(events.indexOf("timer")).toBeLessThan(events.indexOf("complete"));
 const controller=new AbortController();await expect(prepareStroke(source,{signal:controller.signal,workBudget:1,onProgress:()=>controller.abort()})).rejects.toThrow(/cancelled/);
 let called=false;await expect(prepareStroke(source,{signal:controller.signal,onProgress:()=>{called=true;}})).rejects.toThrow(/cancelled/);expect(called).toBe(false);
 const job=new StrokeOutlineJob(source);while(!job.advance(4096).done){}const published=job.result(),copy=structuredClone(published);job.cancel();expect(published).toEqual(copy);expect(source).toEqual(before);
});

import { spawn } from "node:child_process";
import { mkdtempSync, readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import Ajv from "ajv";
import { test, expect } from "bun:test";
import fixture from "../🧫️fixtures/🔣️.json";
import schema from "../🧬️schema/🔣️.json";
import { captureOwnedProcess } from "../🟦️.ts";

const artifactRoot = process.env.SEMIO_TEST_ARTIFACT_DIR;
if (!artifactRoot) throw Error("SEMIO_TEST_ARTIFACT_DIR is required");
type Vector = typeof fixture.cases[number];

/** 🔬️ Observes the same portable process contract through independent Node built-in pipes. */
function oracle(row: Vector, cwd: string): Promise<{ reason: string; status: number | null; stdout: string; stderr: string }> {
  return new Promise(accept => {
    const child = spawn(row.id === "spawn-error" ? join(cwd, "absent-process") : "node", ["-e", row.source], { cwd, env: process.env, stdio: ["ignore", "pipe", "pipe"] });
    let reason = "exit", stdout = Buffer.alloc(0), stderr = Buffer.alloc(0), count = 0;
    const stop = (cause: string) => { if (reason === "exit") { reason = cause; child.kill("SIGKILL"); } };
    const append = (bytes: Buffer, error: boolean) => {
      const retained = bytes.subarray(0, Math.max(0, row.maximumBytes - count));
      if (error) stderr = Buffer.concat([stderr, retained]); else stdout = Buffer.concat([stdout, retained]);
      count += bytes.length;
      if (count > row.maximumBytes) stop("output-limit");
    };
    child.stdout.on("data", bytes => append(bytes, false));
    child.stderr.on("data", bytes => append(bytes, true));
    child.on("error", error => { reason = "spawn-error"; append(Buffer.from(error.message), true); });
    const timeout = row.budgetMs ? setTimeout(() => stop("timeout"), row.budgetMs) : undefined;
    const cancellation = row.cancelAfterMs !== null ? setTimeout(() => stop("cancelled"), row.cancelAfterMs) : undefined;
    child.on("close", status => { clearTimeout(timeout); clearTimeout(cancellation); accept({ reason, status, stdout: stdout.toString("utf8"), stderr: stderr.toString("utf8") }); });
  });
}

test("owned process vectors have strict independent schema admission", () => {
  const validate = new Ajv({ strict: true, allErrors: true }).compile(schema);
  expect(validate(fixture)).toBe(true);
  expect(validate({ ...fixture, extra: true })).toBe(false);
  expect(new Set(fixture.cases.map(row => row.id)).size).toBe(6);
});

for (const row of fixture.cases) test(`owned process capture matches independent Node ${row.id} evidence`, async () => {
  const root = mkdtempSync(join(artifactRoot, "owned-capture-vector-"));
  const independent = await oracle(row, root);
  expect(independent.reason).toBe(row.reason);
  if (row.id !== "spawn-error") expect(independent.status).toBe(row.status);
  if (row.stdout !== null) expect(independent.stdout).toBe(row.stdout);
  if (row.stderr !== null) expect(independent.stderr).toBe(row.stderr);
  const started = Date.now();
  const options = { cwd: root, env: process.env, budgetMs: row.budgetMs, maxOutputBytes: row.maximumBytes, stdoutPath: join(root, "stdout"), stderrPath: join(root, "stderr"), cancelled: () => row.cancelAfterMs !== null && Date.now() - started >= row.cancelAfterMs };
  const result = await captureOwnedProcess(row.id === "spawn-error" ? join(root, "absent-process") : "node", ["-e", row.source], options);
  expect(result.reason).toBe(independent.reason);
  if (row.id !== "spawn-error") expect(result.status).toBe(independent.status);
  if (row.stdout !== null) expect(result.stdout).toBe(independent.stdout);
  if (row.stderr !== null) expect(result.stderr).toBe(independent.stderr);
  if (row.id === "output-limit") expect(result.stdout).toBe(independent.stdout);
  if (row.id === "spawn-error") expect(result.stderr).toContain("ENOENT");
  expect(Buffer.byteLength(result.stdout) + Buffer.byteLength(result.stderr)).toBeLessThanOrEqual(row.maximumBytes);
  expect(readFileSync(options.stdoutPath, "utf8")).toBe(result.stdout);
  expect(readFileSync(options.stderrPath, "utf8")).toBe(result.stderr);
  expect(Date.now() - started).toBeLessThan(5000);
});

test("owned process capture refuses cancellation before child execution", async () => {
  const root = mkdtempSync(join(artifactRoot, "owned-capture-precheck-")), marker = join(root, "spawned");
  const result = await captureOwnedProcess("node", ["-e", "require('node:fs').writeFileSync(process.argv[1],'spawned')", marker], { cwd: root, env: process.env, budgetMs: 0, maxOutputBytes: 1024, stdoutPath: join(root, "stdout"), stderrPath: join(root, "stderr"), cancelled: () => true });
  expect(result).toEqual({ status: null, signal: null, reason: "cancelled", stdout: "", stderr: "" });
  expect(existsSync(marker)).toBe(false);
});

for (const mode of ["exit", "timeout", "cancelled", "output-limit"] as const) {
  test(`exact Cargo process capture retains actual ${mode} evidence`, async () => {
    const artifactRoot = process.env.SEMIO_TEST_ARTIFACT_DIR;
    if (!artifactRoot) throw new Error("SEMIO_TEST_ARTIFACT_DIR is required");
    const root = mkdtempSync(join(artifactRoot, "exact-process-fixture-"));
    const started = Date.now();
    const source = mode === "exit" ? "process.stdout.write('stdout');process.stderr.write('stderr');process.exitCode=7"
      : mode === "output-limit" ? "process.stdout.write('x'.repeat(16384));setInterval(()=>{},1000)"
      : "process.stdout.write('ready');setInterval(()=>{},1000)";
    const options = { cwd: root, env: process.env, budgetMs: mode === "timeout" ? 250 : 0, maxOutputBytes: 1024, stdoutPath: join(root, "stdout"), stderrPath: join(root, "stderr"), cancelled: () => mode === "cancelled" && Date.now() - started >= 150 };
    const result = await captureOwnedProcess(process.execPath, ["-e", source], options);
    expect(result.reason).toBe(mode === "exit" ? "exit" : mode);
    expect(Buffer.byteLength(result.stdout) + Buffer.byteLength(result.stderr)).toBeLessThanOrEqual(1024);
    expect(readFileSync(options.stdoutPath, "utf8")).toBe(result.stdout);
    expect(readFileSync(options.stderrPath, "utf8")).toBe(result.stderr);
    if (mode === "exit") {
      expect(result.status).toBe(7);
      expect(result.stdout).toBe("stdout");
      expect(result.stderr).toBe("stderr");
    }
    expect(Date.now() - started).toBeLessThan(5000);
  });
}

import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import Ajv from "ajv";
import ts from "typescript";
import { TEST_LEVELS, TEST_LEVEL_BUDGET_MS } from "../🟦️.ts";
import fixture from "../🧫️fixtures/🔣️.json" with { type: "json" };
import schema from "../🧬️schema/🔣️.json" with { type: "json" };

test("neutral test vocabulary preserves portable levels and exact budgets", () => {
  expect(new Ajv({ strict: true }).validate(schema, fixture)).toBe(true);
  expect(TEST_LEVELS).toEqual(Object.keys(fixture.levels));
  expect(TEST_LEVEL_BUDGET_MS).toEqual(fixture.levels);
  const source = readFileSync(resolve(import.meta.dir, "../🟦️.ts"), "utf8");
  const javascript = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;
  const exports: Record<string, unknown> = {};
  new Function("exports", javascript)(exports);
  expect(exports.TEST_LEVELS).toEqual(TEST_LEVELS);
  expect(exports.TEST_LEVEL_BUDGET_MS).toEqual(TEST_LEVEL_BUDGET_MS);
  expect(source).not.toContain("🛍️products");
});


test("neutral level selection follows portable CLI and environment laws", async () => {
  const api = await import("../🟦️.ts");
  const keys = ["SEMIO_TEST_LEVEL", "SEMIO_TEST_BUDGET_MS", "SEMIO_COVERAGE"];
  const before = Object.fromEntries(keys.map(key => [key, process.env[key]]));
  try {
    for (const row of fixture.cases) {
      for (const key of keys) delete process.env[key];
      Object.assign(process.env, row.environment);
      const selected = api.resolveTestLevel(row.segments, row.minimum as typeof TEST_LEVELS[number]);
      expect({ ...selected, budgetMs: api.testLevelBudgetMs(), rank: api.testLevelRank(), coverage: process.env.SEMIO_COVERAGE ?? null }).toEqual(row.expected);
      const independent = row.segments[0] in fixture.levels ? row.segments[0] : (row.environment as Record<string, string>).SEMIO_TEST_LEVEL;
      const ranks = Object.keys(fixture.levels);
      const level = ranks[Math.max(Math.max(0, ranks.indexOf(independent ?? "")), ranks.indexOf(row.minimum))]!;
      expect(selected.level).toBe(level);
      expect(api.testLevelAtLeast("long")).toBe(ranks.indexOf(level) >= ranks.indexOf("long"));
      expect(api.atTestLevel({ runIf: (active: boolean) => active }, "quick")).toBe(ranks.indexOf(level) >= ranks.indexOf("quick"));
    }
  } finally { for (const key of keys) { if (before[key] === undefined) delete process.env[key]; else process.env[key] = before[key]; } }
});

import { spawnSync } from "node:child_process";
import { dirname, join, resolve } from "node:path";
import { existsSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import findUp from "find-up";
import { findWorkspaceRoot } from "../🟦️.ts";
import { runScriptMain } from "../🚪️entrypoint/🟦️.ts";
import { expect, test } from "bun:test";
import Ajv from "ajv";
import { Command } from "commander";
import { BundleScript, ScriptRouter } from "../🟦️.ts";
import schema from "../🧬️schema/🔣️.json";
import corpus from "../🧫️fixtures/🔣️.json";

expect(new Ajv({ strict: true }).compile(schema)(corpus)).toBe(true);

for (const row of corpus.cases) test(row.id, async () => {
  const execute = async (oracle: boolean): Promise<typeof row.expected> => {
    const trace: string[] = [], router = new ScriptRouter("/future-owner", "/neutral-workspace");
    const commander = new Command().exitOverride().configureOutput({ writeErr() {}, writeOut() {} });
    for (const owner of row.commands) {
      class OwnedCommand extends BundleScript {
        run(args: string[]): void {
          expect(this.root).toBe("/future-owner");
          expect(this.repoRoot).toBe("/neutral-workspace");
          trace.push(`run:${owner.id}:${args.join(",")}`);
        }
      }
      const load = (): Promise<typeof OwnedCommand> => Promise.resolve().then(() => {
        trace.push(`load:${owner.id}`);
        if (owner.refuse) throw Error("absent owner");
        return OwnedCommand;
      });
      let oracleLoad: Promise<typeof OwnedCommand> | undefined;
      if (oracle) commander.command(owner.id).argument("[args...]").action(async (args: string[]) => {
        const Selected = owner.mode === "lazy" ? await (oracleLoad ??= load()) : OwnedCommand;
        await new Selected("/future-owner", "/neutral-workspace").run(args);
      });
      else if (owner.mode === "lazy") router.registerLazy(owner.id, load);
      else router.register(owner.id, OwnedCommand);
    }
    try {
      const run = (args: string[]): Promise<unknown> => oracle ? commander.parseAsync(args, { from: "user" }) : router.run(args);
      if (row.parallel) await Promise.all(row.requests.map(run));
      else for (const args of row.requests) await run(args);
      return { trace, rejected: false };
    } catch { return { trace, rejected: true }; }
  };
  expect(await execute(true)).toEqual(row.expected);
  expect(await execute(false)).toEqual(row.expected);
});

test("ambiguous registration and absent commands refuse without process termination", async () => {
  const router = new ScriptRouter("/future-owner", "/neutral-workspace");
  class OwnedCommand extends BundleScript { run(): void {} }
  router.register("future", OwnedCommand);
  expect(() => router.register("future", OwnedCommand)).toThrow("already registered");
  expect(() => router.registerLazy("future", async () => OwnedCommand)).toThrow("already registered");
  await expect(router.run(["absent"])).rejects.toThrow("unknown command");
  await expect(router.run([])).rejects.toThrow("usage:");
});


test("keeps routing loadable without any specific product", async () => {
  const { build } = await import("esbuild");
  const source = `import { BundleScript, ScriptRouter } from ${JSON.stringify(resolve(import.meta.dir, "../🟦️.ts"))};
import { runScriptMain } from ${JSON.stringify(resolve(import.meta.dir, "../🚪️entrypoint/🟦️.ts"))};
const corpus = ${JSON.stringify(corpus)};
const results = [];
for (const row of corpus.cases) {
  const trace = [], router = new ScriptRouter("/future-owner", "/neutral-workspace");
  for (const owner of row.commands) {
    class OwnedCommand extends BundleScript { run(args) { trace.push("run:" + owner.id + ":" + args.join(",")); } }
    if (owner.mode === "lazy") router.registerLazy(owner.id, async () => { trace.push("load:" + owner.id); if (owner.refuse) throw Error("absent owner"); return OwnedCommand; });
    else router.register(owner.id, OwnedCommand);
  }
  let rejected = false;
  try { if (row.parallel) await Promise.all(row.requests.map(args => router.run(args))); else for (const args of row.requests) await router.run(args); } catch { rejected = true; }
  results.push({ id: row.id, actual: { trace, rejected } });
}
for (const row of corpus.mainCases) {
  const trace = [], router = new ScriptRouter("/future-owner", "/neutral-workspace");
  for (const id of row.commands) { class OwnedCommand extends BundleScript { run(args) { trace.push("run:" + id + ":" + args.join(",")); } } router.register(id, OwnedCommand); }
  const beforeDispatch = row.interception === "none" ? undefined : async argv => { trace.push("intercept:" + argv.join(",")); if (row.interception === "refuse") throw Error("contribution refused"); return row.interception === "consume"; };
  let rejected = false;
  try { await runScriptMain(router, { argv: row.argv, defaultCommand: row.defaultCommand ?? undefined, beforeDispatch }); } catch { rejected = true; }
  results.push({ id: row.id, actual: { trace, rejected } });
}
console.log(JSON.stringify(results));`;
  const result = await build({ stdin: { contents: source, resolveDir: process.cwd(), sourcefile: "routing-product-refusal.ts" }, bundle: true, platform: "node", format: "esm", write: false, logLevel: "silent", plugins: [{ name: "refuse-specific-products", setup(builder) { builder.onLoad({ filter: /./ }, (args) => { if (args.path.replaceAll("\\", "/").includes("/🧰️framework/🛍️products/")) throw Error(`general routing loads specific product ${args.path}`); }); } }] });
  const child = spawnSync("node", ["--input-type=module", "-e", result.outputFiles[0]!.text], { encoding: "utf8" });
  expect(child.status, child.stderr).toBe(0);
  expect(JSON.parse(child.stdout)).toEqual([...corpus.cases, ...corpus.mainCases].map(row => ({ id: row.id, actual: row.expected })));
});

for (const row of corpus.mainCases) test(row.id, async () => {
  const execute = async (oracle: boolean): Promise<typeof row.expected> => {
    const trace: string[] = [], router = new ScriptRouter("/future-owner", "/neutral-workspace"), commander = new Command().exitOverride().configureOutput({ writeErr() {}, writeOut() {} });
    for (const id of row.commands) {
      class OwnedCommand extends BundleScript { run(args: string[]): void { trace.push(`run:${id}:${args.join(",")}`); } }
      router.register(id, OwnedCommand);
      commander.command(id).argument("[args...]").action((args: string[]) => { trace.push(`run:${id}:${args.join(",")}`); });
    }
    const beforeDispatch = row.interception === "none" ? undefined : async (argv: readonly string[]): Promise<boolean> => {
      trace.push(`intercept:${argv.join(",")}`);
      if (row.interception === "refuse") throw Error("contribution refused");
      return row.interception === "consume";
    };
    try {
      if (oracle) {
        if (await beforeDispatch?.(row.argv)) return { trace, rejected: false };
        const argv = row.argv.length ? row.argv : row.defaultCommand ? [row.defaultCommand] : [];
        if (!row.commands.length || !argv.length) throw Error("missing command");
        await commander.parseAsync(argv, { from: "user" });
      } else await runScriptMain(router, { argv: row.argv, defaultCommand: row.defaultCommand ?? undefined, beforeDispatch });
      return { trace, rejected: false };
    } catch { return { trace, rejected: true }; }
  };
  expect(await execute(true)).toEqual(row.expected);
  expect(await execute(false)).toEqual(row.expected);
});

for (const row of corpus.workspaceCases) test(row.id, () => {
  const root = mkdtempSync(join(process.env.SEMIO_TEST_ARTIFACT_DIR ?? tmpdir(), "process-root-"));
  try {
    mkdirSync(resolve(root, row.start), { recursive: true });
    for (const marker of row.markers) {
      mkdirSync(resolve(root, marker.directory), { recursive: true });
      for (const filename of marker.files) writeFileSync(resolve(root, marker.directory, filename), "{}");
    }
    const oracle = findUp.sync((directory: string) => existsSync(join(directory, "nx.json")) && existsSync(join(directory, "package.json")) ? "nx.json" : directory === root ? findUp.stop : undefined, { cwd: resolve(root, row.start) });
    const expected = row.expected === null ? undefined : resolve(root, row.expected);
    expect(oracle === undefined ? undefined : dirname(oracle)).toBe(expected);
    if (expected === undefined) expect(() => findWorkspaceRoot(resolve(root, row.start), { stopAt: root })).toThrow("workspace root");
    else expect(findWorkspaceRoot(resolve(root, row.start), { stopAt: root })).toBe(expected);
  } finally { rmSync(root, { recursive: true, force: true }); }
});

