/** 🎭️Proves native primitive equivalence and customization of actual edge/gallery styles. */
export async function proveStylingColorPrimitivesV1(): Promise<number> {
  assert.equal(new Ajv({ strict: true }).compile(schema)(corpus), true);
  for (const row of corpus.colors) {
    assert.deepEqual(colorString.get(row.before)?.value, row.rgba, row.id + ": independent original color");
    assert.deepEqual(colorString.get(row.after)?.value, row.rgba, row.id + ": independent canonical color");
  }
  const css = readFileSync(new URL("../../../🖌️ui/🎨️.css", import.meta.url), "utf8");
  const edgeRule = /\.temp \.react-flow__edge-path\s*\{[^}]*\}/.exec(css)?.[0];
  assert.ok(edgeRule?.includes("stroke: var(--color-primary)"), "actual edge accent consumes the semantic variable");
  const browser = await chromium.launch({ headless: true });
  try {
    const page = await browser.newPage();
    await page.setContent("<style>" + edgeRule + "</style><svg class='temp'><path class='react-flow__edge-path'/></svg>");
    const result = await page.evaluate(colors => {
      const properties = ["color", "boxShadow", "maskImage"] as const;
      const observed = colors.map(row => properties.map(property => {
        const evaluate = (color: string): string => {
          const element = document.createElement("div");
          element.style[property] = property === "color" ? color : property === "boxShadow" ? "0 1px 2px " + color : "linear-gradient(" + color + ", " + color + ")";
          document.body.append(element);
          const value = getComputedStyle(element)[property];
          element.remove();
          return value;
        };
        return [evaluate(row.before), evaluate(row.after)];
      }));
      const edge = document.querySelector(".react-flow__edge-path")!;
      const accents = ["black", "white"].map(color => {
        document.documentElement.style.setProperty("--color-primary", color);
        return getComputedStyle(edge).stroke;
      });
      const escaped = document.createElement("div");
      escaped.style.cssText = "color: \\23 abc;";
      return { observed, accents, escapedColor: escaped.style.color };
    }, corpus.colors);
    let assertions = 0;
    for (const properties of result.observed) for (const [before, after] of properties) {
      assert.notEqual(before, "none", "native primitive syntax is admitted");
      assert.equal(before, after, "native alpha and paint computation is unchanged");
      assertions++;
    }
    assert.deepEqual(result.accents, ["rgb(0, 0, 0)", "rgb(255, 255, 255)"]);
    assert.equal(result.escapedColor, "", "escaped hash is an identifier, not a CSS color");
    const gallery = renderToStaticMarkup(createElement(Fragment, null,
      createElement("article", { id: "gallery-card", style: galleryCardStyle }),
      createElement("div", { id: "gallery-swatches" }, createElement(SwatchGrid, { title: "Owned Palette", entries: [["sample", [255, 255, 255, 255]]] })),
      createElement("div", { id: "gallery-table" }, createElement(DataTable, { columns: ["Owned Token"], rows: [["sample"]] }))));
    await page.setContent(gallery);
    const chrome = await page.evaluate(rows => ["black", "white"].map(color => {
      document.documentElement.style.setProperty("--border-normal-color", color);
      return rows.map(row => {
        const element = document.querySelector(row.selector);
        if (!element) throw Error("Missing actual gallery element: " + row.id);
        const paint = getComputedStyle(element).getPropertyValue(row.property === "borderTopColor" ? "border-top-color" : "border-bottom-color");
        const canvas = document.createElement("canvas");
        canvas.width = canvas.height = 1;
        const context = canvas.getContext("2d")!;
        context.fillStyle = paint;
        context.fillRect(0, 0, 1, 1);
        return [...context.getImageData(0, 0, 1, 1).data];
      });
    }), corpus.galleries);
    for (const [index, color] of ["black", "white"].entries()) for (const [rowIndex, row] of corpus.galleries.entries()) {
      const rgb = colorString.get(color)!.value.slice(0, 3);
      assert.deepEqual(chrome[index]![rowIndex], [...rgb, Math.round(row.alpha * 255)], row.id + ": native semantic border " + color);
      assertions++;
    }
    return assertions + result.accents.length + 1;
  } finally {
    await browser.close();
  }
}

import assert from "node:assert/strict";
import Ajv from "ajv";
import { compile } from "tailwindcss";
import { chromium } from "playwright";
import corpus from "../../🧫️fixtures/📏️relative-sizing/🔣️.json";
import schema from "../../🧬️schema/📏️relative-sizing/🔣️.json";

const utilities = [
  ["w", "width"], ["h", "height"], ["min-w", "minWidth"], ["max-w", "maxWidth"],
  ["min-h", "minHeight"], ["max-h", "maxHeight"], ["gap", "gap"],
  ["text", "fontSize"], ["leading", "lineHeight"],
] as const;

/** 📏️Proves authored relative dimensions through actual Tailwind utilities and Chromium. */
export async function proveRelativeStylingSizesV1(): Promise<number> {
  assert.equal(new Ajv({ strict: true }).compile(schema)(corpus), true);
  for (const row of corpus.sizes) {
    assert.equal(row.pixels.length, corpus.rootFontSizesPx.length);
    assert.deepEqual(corpus.rootFontSizesPx.map(font => Number.parseFloat(row.rem) * font), row.pixels);
  }
  const compiler = await compile("@tailwind utilities;");
  const classes = [...corpus.sizes.flatMap(row => utilities.map(([prefix]) => prefix + "-[" + row.rem + "]")), ...corpus.rounding.map(row => row.semanticClass)];
  const css = compiler.build(classes);
  const browser = await chromium.launch({ headless: true });
  try {
    const page = await browser.newPage();
    await page.setContent("<style>" + css + "</style>");
    const measurements = await page.evaluate(({ sizes, roots, utilities }) => roots.map(root => {
      document.documentElement.style.fontSize = root + "px";
      return sizes.map(row => utilities.map(([prefix, property]) => {
        const element = document.createElement("div");
        element.className = prefix + "-[" + row.rem + "]";
        document.body.append(element);
        const value = Number.parseFloat(getComputedStyle(element)[property]);
        element.remove();
        return value;
      }));
    }), { sizes: corpus.sizes, roots: corpus.rootFontSizesPx, utilities });
    let assertions = 0;
    corpus.rootFontSizesPx.forEach((root, rootIndex) => corpus.sizes.forEach((row, sizeIndex) => utilities.forEach(([prefix], utilityIndex) => {
      assert.equal(measurements[rootIndex]![sizeIndex]![utilityIndex], row.pixels[rootIndex], prefix + "-[" + row.rem + "] at " + root + "px");
      assertions++;
    })));
    for (const root of corpus.rootFontSizesPx) for (const row of corpus.rounding) {
      await page.setContent("<style>" + css + "</style><div id=\"capsule\"></div>");
      await page.evaluate(({ root, row }) => {
        document.documentElement.style.fontSize = root + "px";
        document.body.style.margin = "0";
        document.body.style.background = "white";
        const element = document.getElementById("capsule")!;
        element.style.width = row.widthRem + "rem";
        element.style.height = row.heightRem + "rem";
        element.style.background = "black";
        element.style.borderRadius = Math.min(row.widthRem, row.heightRem) * root / 2 + "px";
      }, { root, row });
      const shape = () => page.locator("#capsule").evaluate(element => {
        const box = element.getBoundingClientRect(), radius = Math.min(box.width, box.height) / 2;
        const hit = (x: number, y: number) => document.elementFromPoint(box.x + x, box.y + y) === element;
        const corners = [false, true].flatMap(right => [false, true].map(bottom => hit(right ? box.width - radius * 0.05 : radius * 0.05, bottom ? box.height - radius * 0.05 : radius * 0.05)));
        return { width: box.width, height: box.height, center: hit(box.width / 2, box.height / 2), corners };
      });
      const reference = await shape();
      await page.locator("#capsule").evaluate((element, className) => {
        element.style.borderRadius = "";
        element.className = className;
      }, row.semanticClass);
      const actual = await shape();
      assert.equal(reference.center, true, row.id + " native reference center");
      assert.deepEqual(reference.corners, [false, false, false, false], row.id + " native reference corners");
      assert.deepEqual(actual, reference, row.id + " capsule bounds, center and clipped corners at " + root + "px");
      const radius = await page.locator("#capsule").evaluate(element => Number.parseFloat(getComputedStyle(element).borderTopLeftRadius));
      assert.equal(radius >= Math.min(actual.width, actual.height) / 2, true, row.id + " full capsule radius at " + root + "px");
      assertions += 4;
    }
    return assertions;
  } finally {
    await browser.close();
  }
}

import assert from "node:assert/strict";
import Ajv from "ajv";
import ts from "typescript";
import colorString from "color-string";
import { resolve } from "node:path";
import schema from "../🧬️schema/🔣️.json";
import corpus from "../🧫️fixtures/🔣️.json";
import * as verification from "../🟦️.ts";

/** 🛡️Proves explicit owner scopes and source rules against AJV and TypeScript syntax. */
export function proveStylingVerificationContractV1(): number {
  const ajv = new Ajv({ strict: true }).addSchema(schema);
  assert.equal(ajv.getSchema(`${schema.$id}#/$defs/CasesV1`)!(corpus), true);
  const validate = ajv.getSchema(`${schema.$id}#/$defs/ScopeV1`)!;
  const applicationSource = ajv.getSchema(`${schema.$id}#/$defs/ApplicationPathV1`)!;
  const colorSource = ajv.getSchema(`${schema.$id}#/$defs/ColorApplicationPathV1`)!;
  const failures: string[] = [];
  const manifestOracle = ajv.getSchema(`${schema.$id}#/$defs/SourceManifestV1`)!;
  for (const row of corpus.sources) {
    const input = row.input as { roots: string[]; files: string[] };
    const canonical = (paths: string[]): boolean => paths.every(path => path.normalize("NFC") === path) && new Set(paths).size === new Set(paths.map(path => path.toLowerCase())).size;
    assert.equal(manifestOracle(input) && canonical(input.roots) && canonical(input.files), row.accepted, row.id + ": AJV source oracle");
    let accepted = false, files: readonly string[] = [];
    try { files = verification.admitStylingSourceManifestV1(input).files; accepted = true; } catch {}
    if (accepted !== row.accepted || JSON.stringify(files) !== JSON.stringify(row.files)) failures.push(row.id);
  }
  for (const row of corpus.scopes) {
    const roots = (row.input as { roots: string[] }).roots;
    const oracle = validate(row.input) && roots.every(path => path.normalize("NFC") === path) && new Set(roots).size === new Set(roots.map(path => path.toLowerCase())).size;
    assert.equal(oracle, row.accepted, `${row.id}: AJV path oracle`);
    let accepted = false, actual: readonly string[] = [];
    try { actual = verification.admitStylingScanScopeV1(row.input).roots; accepted = true; } catch {}
    if (accepted !== row.accepted || JSON.stringify(actual) !== JSON.stringify(row.roots)) failures.push(row.id);
  }
  for (const row of corpus.scans) {
    const files = row.files as Record<string, string>;
    const source = { roots: row.roots, files: Object.keys(files), readText: (path: string) => files[path]! };
    const literals: string[] = [], colorLiterals: string[] = [];
    for (const [path, text] of Object.entries(files)) {
      if (!row.roots.some(root => path.startsWith(`${root}/`)) || !applicationSource(path)) continue;
      const walk = (node: ts.Node): void => { if (ts.isStringLiteralLike(node)) { literals.push(node.text); if (colorSource(path)) colorLiterals.push(node.text); } ts.forEachChild(node, walk); };
      walk(ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX));
    }
    assert.equal(literals.some(value => /\[(?:-?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+))px\]/u.test(value)), row.expected.px.length > 0, `${row.id}: TypeScript sizing oracle`);
    const colors = colorLiterals.flatMap(value => value.match(/[^\s]*#[^\s]*|\b(?:rgba?|hsla?)\([^)]*\)/g) ?? []);
    assert.equal(colors.some(value => colorString.get(value) !== null), row.expected.color.length > 0, `${row.id}: TypeScript and color-string oracle`);
    for (const kind of ["px", "color"] as const) {
      try {
        const findings = verification.collectStylingViolationsV1(source, kind);
        assert.equal(ajv.compile({ type: "array", items: { $ref: `${schema.$id}#/$defs/ViolationV1` } })(findings), true);
        assert.deepEqual(findings.map(finding => finding.kind), row.expected[kind]);
      }
      catch { failures.push(`${row.id}:${kind}`); }
    }
  }
  assert.deepEqual(failures, [], "Styling verification differs from the portable corpus");
  return corpus.scopes.length + corpus.sources.length + corpus.scans.length;
}

/** 🟢️Executes the same portable source contract through independent esbuild and Node. */
export async function proveIndependentStylingVerificationContractV1(): Promise<void> {
  const { build } = await import("esbuild");
  const path = resolve(import.meta.dirname, "🟦️.ts");
  const products = resolve(import.meta.dirname, "../../../../../🛍️products") + "/";
  const program = `import { proveStylingVerificationContractV1 } from ${JSON.stringify(path)}; process.stdout.write(JSON.stringify({ vectors: proveStylingVerificationContractV1() }));`;
  const result = await build({ stdin: { contents: program, resolveDir: import.meta.dirname, loader: "ts" }, bundle: true, platform: "node", format: "esm", external: ["typescript"], write: false, plugins: [{ name: "framework-product-removal", setup(builder) {
    builder.onLoad({ filter: /.*/ }, input => input.path.replaceAll("\\", "/").startsWith(products.replaceAll("\\", "/")) ? { errors: [{ text: "General styling imports a concrete framework product: " + input.path }] } : undefined);
  } }] });
  const node = Bun.spawnSync(["node", "--input-type=module"], { stdin: Buffer.from(result.outputFiles![0]!.text), stdout: "pipe", stderr: "pipe" });
  assert.equal(node.exitCode, 0, Buffer.from(node.stderr).toString());
  assert.deepEqual(JSON.parse(Buffer.from(node.stdout).toString()), { vectors: corpus.scopes.length + corpus.sources.length + corpus.scans.length });
}

