    expect(uiCss).toMatch(/\[data-slot="panel-tabs"\] > \[data-slot="panel-tab-button"\]:not\(:last-child\)\s*\{\s*box-shadow:\s*inset calc\(-1 \* var\(--stroke-hairline\)\) 0 0 0 var\(--border-normal-color\);/);
