      "data-ui-state": "previewed",
      "data-ui-status": "waiting",
      "data-ui-hover": "true",
      "data-ui-selected": "true",
    });
  });

  it("resolveElementFillKind follows disabled > celebrated > selected > previewed > hovered > neutral precedence", () => {
