  versionFunctions: readonly Readonly<{ name: string; descriptor: "ArtifactSchemaDescriptor" | "AppSchemaDescriptor"; facet: string }>[];
  states: readonly Readonly<{ variant: string; wire: string; kebab: string; graphql: string }>[];
